import pytest

from bedrock_protocol import v975, v1001

# generated by gophertunnel de090ae:
# &packet.GraphicsOverrideParameter{Values: []protocol.ParameterKeyframeValue{{Time: 0.5, Value: mgl32.Vec3{1, 2, 3}}},
# FloatValue: protocol.Option[float32](0.25), BiomeIdentifier: "plains", ParameterType:
# protocol.GraphicsOverrideParameterTypeWavesDepth, Reset: true}
V975 = bytes.fromhex("010000003f0000803f0000004000004040010000803e0006706c61696e730d01")

# generated by gophertunnel 654cd5f:
# &packet.GraphicsOverrideParameter{Values: []protocol.ParameterKeyframeValue{{Time: 0.5, Value: mgl32.Vec3{1, 2, 3}}},
# FloatValue: protocol.Option[float32](0.25), BiomeIdentifier: "plains", PlayerIdentifier: protocol.Option("steve"),
# ParameterType: protocol.GraphicsOverrideParameterTypeWavesDepth, Reset: true}
V1001 = bytes.fromhex("010000003f0000803f0000004000004040010000803e0006706c61696e73010573746576650d01")

# generated by gophertunnel 654cd5f:
# &packet.GraphicsOverrideParameter{Values: []protocol.ParameterKeyframeValue{{Time: 0.5, Value: mgl32.Vec3{1, 2, 3}}},
# FloatValue: protocol.Option[float32](0.25), BiomeIdentifier: "plains", ParameterType:
# protocol.GraphicsOverrideParameterTypeWavesDepth, Reset: true}
V1001_WITHOUT_PLAYER = bytes.fromhex("010000003f0000803f0000004000004040010000803e0006706c61696e73000d01")

GOLDENS = [
    pytest.param(
        v975.GraphicsOverrideParameterPacket(
            keyframes={0.5: v975.Vec3(x=1.0, y=2.0, z=3.0)},
            float_value=0.25,
            biome_id="plains",
            parameter_id=v975.GraphicsOverrideParameterType.WAVES_DEPTH,
            reset_parameter=True,
        ),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.GraphicsOverrideParameterPacket(
            keyframes={0.5: v1001.Vec3(x=1.0, y=2.0, z=3.0)},
            float_value=0.25,
            biome_id="plains",
            player_id="steve",
            parameter_id=v1001.GraphicsOverrideParameterType.WAVES_DEPTH,
            reset_parameter=True,
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v1001.GraphicsOverrideParameterPacket(
            keyframes={0.5: v1001.Vec3(x=1.0, y=2.0, z=3.0)},
            float_value=0.25,
            biome_id="plains",
            player_id=None,
            parameter_id=v1001.GraphicsOverrideParameterType.WAVES_DEPTH,
            reset_parameter=True,
        ),
        V1001_WITHOUT_PLAYER,
        id="v1001-without-player",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001])
def test_graphics_override_parameter_is_packet_331(version):
    assert version.PACKETS[331] is version.GraphicsOverrideParameterPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_graphics_override_parameter_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_graphics_override_parameter_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_990_player_id_leaves_the_rest_of_the_body_unchanged():
    assert V1001[:30] + V1001[37:] == V975
